#!/usr/bin/env python3
"""Solve DD tables for deals generated by the harness's own make_board.

Writes one JSON line per deal as soon as it is solved, so partial output is usable.
Usage: solve_tables.py SEED SPLIT START COUNT OUT.jsonl [WORKERS]
"""
import json
import multiprocessing as mp
import os
import sys
import time

sys.path.insert(0, '/home/claude/gen5r')
from bridge_harness.bidding_env import TableSolver, make_board, deal_key  # noqa: E402

LIB = '/home/claude/gen5r/bridge_harness/libbridge_dds.so'
_solver = None


def _init():
    global _solver
    _solver = TableSolver(LIB)


def _solve(args):
    seed, index, split = args
    board = make_board(seed, index, split)
    table = _solver.solve(board.hands)
    return dict(index=index, key=deal_key(board.hands), family=deal_key(board.hands, True),
                hands=[list(map(int, h)) for h in board.hands], dealer=int(board.dealer),
                vulnerability=board.vulnerability, dds=table)


def main():
    seed, split, start, count, out = int(sys.argv[1]), sys.argv[2], int(sys.argv[3]), int(sys.argv[4]), sys.argv[5]
    workers = int(sys.argv[6]) if len(sys.argv) > 6 else 2
    done = set()
    if os.path.exists(out):
        with open(out) as handle:
            for line in handle:
                try:
                    done.add(json.loads(line)['index'])
                except Exception:
                    pass
    todo = [(seed, i, split) for i in range(start, start + count) if i not in done]
    started = time.time()
    with mp.get_context('spawn').Pool(workers, initializer=_init) as pool, open(out, 'a') as handle:
        for n, row in enumerate(pool.imap(_solve, todo, chunksize=4), 1):
            handle.write(json.dumps(row, separators=(',', ':')) + '\n')
            if n % 50 == 0:
                handle.flush()
            if n % 500 == 0 or n == len(todo):
                print(f'{out}: {n}/{len(todo)} solved, {time.time() - started:.0f}s', flush=True)


if __name__ == '__main__':
    main()
